import { resolve } from "node:path";

import { describe, expect, test } from "bun:test";

const repoRoot = resolve(import.meta.dirname, "../../..");
const workflowPath = resolve(repoRoot, ".github/workflows/drupal-journey.yml");

const GENERATED_HEADER =
  "# Generated by scripts/codegen.ts — do not hand-edit. Edit scripts/build-drupal-journey-workflow.ts instead.";

const PLATFORM_IDS = [
  "linux-x64",
  "linux-arm64",
  "darwin-arm64",
  "darwin-x64",
  "windows-x64",
  "windows-arm64",
] as const;

const SCHEDULED_IDS = ["darwin-arm64", "darwin-x64", "windows-x64", "windows-arm64"] as const;
const LINUX_IDS = ["linux-x64", "linux-arm64"] as const;

const SETUP_FLAGS = "--yes --provider=lando --skip-install-ca --skip-shell-integration --skip-file-sync";
const JOURNEY = "bun run scripts/drupal-journey.ts";
const SCHEDULE_IF = "if: github.event_name == 'schedule' || github.event_name == 'workflow_dispatch'";
const LINUX_SOURCE_BUILD_MARKERS =
  "uses: actions/setup-go@|go-version: 1.25.6|dtolnay/rust-toolchain@|libcap-dev|libsqlite3-dev|libseccomp-dev|protobuf-compiler|uidmap".split(
    "|",
  );

const readWorkflow = async (): Promise<string> => Bun.file(workflowPath).text();

const findIndentedBlock = (source: string, key: string, indent = 0): string => {
  const lines = source.split("\n");
  const start = lines.findIndex((line) => line === `${" ".repeat(indent)}${key}:`);
  expect(start).toBeGreaterThanOrEqual(0);

  const childIndent = indent + 2;
  const block: Array<string> = [];

  for (const line of lines.slice(start + 1)) {
    if (line.trim() === "") {
      block.push(line);
      continue;
    }

    const lineIndent = line.length - line.trimStart().length;
    if (lineIndent < childIndent) break;
    block.push(line);
  }

  return block.join("\n");
};

const jobBlock = (workflow: string, id: (typeof PLATFORM_IDS)[number]): string => {
  const jobs = findIndentedBlock(workflow, "jobs");
  return findIndentedBlock(jobs, `drupal-journey-${id}`, 2);
};

describe("drupal-journey workflow", () => {
  test("starts with the generated-file header and six platform jobs", async () => {
    // Given / When
    const workflow = await readWorkflow();
    const jobs = findIndentedBlock(workflow, "jobs");

    // Then
    expect(workflow.startsWith(`${GENERATED_HEADER}\n`)).toBe(true);
    for (const id of PLATFORM_IDS) {
      expect(jobs).toContain(`  drupal-journey-${id}:`);
    }
  });

  test("triggers on pull_request, schedule, and workflow_dispatch", async () => {
    // Given / When
    const triggers = findIndentedBlock(await readWorkflow(), "on");

    // Then
    expect(triggers).toContain("pull_request");
    expect(triggers).toContain("schedule");
    expect(triggers).toContain("workflow_dispatch");
  });

  test("runs every job with bash so Windows cells can execute POSIX compile steps", async () => {
    // Given / When
    const workflow = await readWorkflow();

    // Then
    expect(workflow).toContain("defaults:\n  run:\n    shell: bash");
  });

  test("runs linux-x64 on ubuntu-24.04 with lando setup, assemble, and a hard journey gate", async () => {
    // Given / When
    const linuxX64 = jobBlock(await readWorkflow(), "linux-x64");

    // Then
    expect(linuxX64).toContain("    runs-on: ubuntu-24.04");
    expect(linuxX64).toContain(SETUP_FLAGS);
    expect(linuxX64).toContain("--platform linux-x64");
    expect(linuxX64).toContain(JOURNEY);
    expect(linuxX64).not.toContain(`${JOURNEY} || true`);
  });

  test("runs linux-arm64 on ubuntu-24.04-arm with the same setup flags and journey", async () => {
    // Given / When
    const linuxArm64 = jobBlock(await readWorkflow(), "linux-arm64");

    // Then
    expect(linuxArm64).toContain("    runs-on: ubuntu-24.04-arm");
    expect(linuxArm64).toContain(SETUP_FLAGS);
    expect(linuxArm64).toContain("--platform linux-arm64");
    expect(linuxArm64).toContain(JOURNEY);
    expect(linuxArm64).not.toContain(`${JOURNEY} || true`);
  });

  test("installs Linux source-build prerequisites before linux current-commit assemble", async () => {
    // Given / When
    const workflow = await readWorkflow();

    // Then
    for (const id of LINUX_IDS) {
      const job = jobBlock(workflow, id);
      const installPrereqs = job.indexOf("Install Linux Podman source-build prerequisites");
      const assemble = job.indexOf(`Assemble current-commit ${id} runtime bundle`);
      expect(installPrereqs).toBeGreaterThan(-1);
      expect(assemble).toBeGreaterThan(installPrereqs);
      for (const prerequisite of LINUX_SOURCE_BUILD_MARKERS) {
        expect(job).toContain(prerequisite);
      }
    }
  });

  test("does not install Linux source-build toolchains on non-linux cells", async () => {
    // Given / When
    const workflow = await readWorkflow();

    // Then
    for (const id of SCHEDULED_IDS) {
      const job = jobBlock(workflow, id);
      expect(job).not.toContain("actions/setup-go@");
      expect(job).not.toContain("dtolnay/rust-toolchain@");
    }
  });

  test("gates darwin and windows cells to schedule or workflow_dispatch", async () => {
    // Given / When
    const workflow = await readWorkflow();

    // Then
    for (const id of SCHEDULED_IDS) {
      expect(jobBlock(workflow, id)).toContain(SCHEDULE_IF);
    }
  });

  test("runs darwin-arm64 on self-hosted lando virt with provider lando", async () => {
    // Given / When
    const darwinArm64 = jobBlock(await readWorkflow(), "darwin-arm64");

    // Then
    expect(darwinArm64).toContain("    runs-on: [self-hosted, lando-virt, macOS, ARM64]");
    expect(darwinArm64).toContain("--provider=lando");
    expect(darwinArm64).not.toContain("continue-on-error");
  });

  test("runs darwin-x64 on self-hosted Intel Mac with docker and without Docker Desktop", async () => {
    // Given / When
    const darwinX64 = jobBlock(await readWorkflow(), "darwin-x64");

    // Then
    expect(darwinX64).toContain("    runs-on: [self-hosted, lando-virt, macOS, X64]");
    expect(darwinX64).toContain("--provider=docker");
    expect(darwinX64).not.toContain("docker/setup-docker");
    expect(darwinX64).not.toContain("Docker Desktop");
    expect(darwinX64).not.toContain("macos-15-intel");
  });

  test("runs windows-x64 on self-hosted with win32-x64 assemble and without managed-setup acceptance", async () => {
    // Given / When
    const windowsX64 = jobBlock(await readWorkflow(), "windows-x64");

    // Then
    expect(windowsX64).toContain("    runs-on: [self-hosted, lando-virt, Windows, X64]");
    expect(windowsX64).toContain("win32-x64");
    expect(windowsX64).not.toContain("windows-managed-setup-acceptance.ts");
  });

  test("runs windows-arm64 on self-hosted with win32-arm64 assemble", async () => {
    // Given / When
    const windowsArm64 = jobBlock(await readWorkflow(), "windows-arm64");

    // Then
    expect(windowsArm64).toContain("    runs-on: [self-hosted, lando-virt, Windows, ARM64]");
    expect(windowsArm64).toContain("--platform win32-arm64");
  });

  test("isolates LANDO_USER roots and forbids continue-on-error and advisory skips", async () => {
    // Given / When
    const workflow = await readWorkflow();

    // Then
    expect(workflow).toContain("LANDO_USER_CONF_ROOT");
    expect(workflow).toContain("LANDO_USER_DATA_ROOT");
    expect(workflow).toContain("LANDO_USER_CACHE_ROOT");
    expect(workflow).not.toContain("continue-on-error: true");
    expect(workflow).not.toContain("advisory-skip");
  });

  test("runs setup before the Drupal journey on every cell", async () => {
    // Given / When
    const workflow = await readWorkflow();

    // Then
    for (const id of PLATFORM_IDS) {
      const job = jobBlock(workflow, id);
      const setup = job.indexOf("Setup provider");
      const journey = job.indexOf("Run Drupal journey");
      expect(setup).toBeGreaterThan(-1);
      expect(journey).toBeGreaterThan(setup);
    }
  });

  test("sets timeout-minutes: 90 on every job", async () => {
    // Given / When
    const workflow = await readWorkflow();

    // Then
    for (const id of PLATFORM_IDS) {
      expect(jobBlock(workflow, id)).toContain("timeout-minutes: 90");
    }
  });

  test("sets COMPOSER_PROCESS_TIMEOUT for Composer-heavy Drupal installs", async () => {
    // Given / When
    const workflow = await readWorkflow();

    // Then
    expect(workflow).toContain("COMPOSER_PROCESS_TIMEOUT");
  });

  test("always runs teardown and evidence upload", async () => {
    // Given / When
    const workflow = await readWorkflow();

    // Then
    for (const id of PLATFORM_IDS) {
      const job = jobBlock(workflow, id);
      expect(job).toContain("Teardown");
      expect(job).toContain("Upload evidence");
      expect(job).toContain("if: always()");
    }
  });

  test("names the linux-x64 evidence artifact after the job id", async () => {
    // Given / When
    const linuxX64 = jobBlock(await readWorkflow(), "linux-x64");

    // Then
    expect(linuxX64).toContain("name: drupal-journey-linux-x64");
  });

  test("passes --report to the Drupal journey script", async () => {
    // Given / When
    const linuxX64 = jobBlock(await readWorkflow(), "linux-x64");

    // Then
    expect(linuxX64).toContain("--report");
    expect(linuxX64).toContain("scripts/drupal-journey.ts");
  });

  test("does not mark the linux-x64 job continue-on-error", async () => {
    // Given / When
    const linuxX64 = jobBlock(await readWorkflow(), "linux-x64");

    // Then
    expect(linuxX64).not.toContain("continue-on-error");
  });

  test("teardown destroy uses a workspace-absolute compiled binary", async () => {
    // Given: the generated Drupal journey workflow.
    // When: teardown is inspected on every cell.
    // Then: destroy runs via $GITHUB_WORKSPACE/dist/<binary>, not a cwd-relative dist/ path after cd.
    const workflow = await readWorkflow();
    for (const id of PLATFORM_IDS) {
      const job = jobBlock(workflow, id);
      expect(job).toContain('BINARY="$GITHUB_WORKSPACE/dist/');
      expect(job).toContain('"$BINARY" destroy -y');
      expect(job).not.toContain("&& dist/");
    }
  });
});
